#!/bin/bash
# ============================================================================
# Downloads the results of every node of ips.txt.
#
# USAGE: bash V3_Collect.sh [target folder]
# On each node the result folders, the stored suites and the logs are packed
# into one archive; the raw GUITAR test files and the product model files are
# left out (they are regenerated by the pipeline). The archive of node i is
# unpacked into <target>/node<i>/ after its checksum is compared with the node's.
# Exit code 1 and a list of the nodes with a problem unless every node of
# ips.txt is collected. Do not delete a machine before this script says COMPLETE.
# ============================================================================
set -u
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
IPS_FILE="$SCRIPT_DIR/ips.txt"
TARGET=${1:-"$SCRIPT_DIR/../../../results/v3-$(date +%Y%m%d_%H%M%S)"}
mkdir -p "$TARGET"
# V3_REMOTE, V3_TAG, V3_MAIN_LOG: folder of the repository on the nodes, prefix of the archive
# names and log of the run, for a run that was started from a second copy of the repository.
REMOTE=${V3_REMOTE:-/root/esg-with-feature-expressions}
TAG=${V3_TAG:-v3}
MAIN_LOG=${V3_MAIN_LOG:-/root/main_run.log}

index=0; collected=0; listed=0; problems=""
while IFS= read -r line || [ -n "$line" ]; do
    ip=$(echo "$line" | awk '{print $1}')
    case "$ip" in ''|'#'*) continue ;; esac
    node="node$(printf '%02d' "$index")"; index=$((index + 1)); listed=$((listed + 1))
    echo "== $node ($ip)"
    state=$(ssh -n -o StrictHostKeyChecking=no -o ConnectTimeout=20 "root@$ip" \
        "test -f $REMOTE/files/logs/v3/ALL_DONE && echo done || echo running; pgrep -c java; awk -F';' 'NR>1{f+=\$7} END{print f+0}' $REMOTE/files/logs/v3/jobs.csv; tail -n 1 $REMOTE/files/logs/v3/jobs.csv")
    if [ -z "$state" ]; then
        echo "   UNREACHABLE"; problems="$problems $node:unreachable"; continue
    fi
    set -- $state
    echo "   state: $1, JVMs running: $2, failed JVMs in jobs.csv: $3, last job: ${4:-}"
    [ "$3" = "0" ] || problems="$problems $node:failed-JVMs=$3"
    if [ "$1" != "done" ] || [ "$2" != "0" ]; then
        # Packing uses the processors of the node, so a node that still measures is left alone.
        [ "${V3_COLLECT_UNFINISHED:-0}" = "1" ] || { echo "   NOT FINISHED, skipped"; problems="$problems $node:not-finished"; continue; }
    fi
    # Two archives: the results (unpacked here) and the logs (kept packed; the output of
    # GUITAR makes them large and they are only needed to look up a failure). The messages of
    # tar are kept in /root/${TAG}_pack.err; a file that is missing from the list is reported there.
    sizes=$(ssh -n "root@$ip" "cd $REMOTE && tar czf /root/${TAG}_$node.tgz \
        --exclude='*.tst' --exclude='*.EFG' --exclude='*.DOT' --exclude='*.dot' --exclude='files/archive_before_*' \
        files/logs/v3/jobs.csv files/logs/v3/node_info*.txt files/logs/v3/ALL_DONE \
        files/Cases/*/testsequences files/Cases/*/comparativeEfficiencyTestPipeline \
        files/Cases/*/extremeScalabilityTestPipeline files/Cases/*/faultdetection files/Cases/*/EFGs/efg_results \
        files/Cases/*/EFGs/efg_testsequences/stored files/Cases/*/*_ProductConfigurations.txt \
        files/Cases/*/EFGs/*_Generation_Times.csv files/Cases/*/DOTs/*_Generation_Times.csv 2> /root/${TAG}_pack.err; \
        echo tar=\$? >> /root/${TAG}_pack.err; \
        tar cf - files/logs $MAIN_LOG 2>> /root/${TAG}_pack.err | xz -T0 -3 > /root/${TAG}_${node}_logs.tar.xz; \
        echo \$(stat -c %s /root/${TAG}_$node.tgz) \$(stat -c %s /root/${TAG}_${node}_logs.tar.xz) \
             \$(sha256sum /root/${TAG}_$node.tgz | cut -d' ' -f1) \$(sha256sum /root/${TAG}_${node}_logs.tar.xz | cut -d' ' -f1) \
             \$(tar tzf /root/${TAG}_$node.tgz | wc -l)")
    set -- $sizes
    if [ "$#" -ne 5 ]; then
        echo "   PACKING FAILED (no sizes returned)"; problems="$problems $node:packing"; continue
    fi
    echo "   results $(( $1 / 1048576 )) MB packed ($5 entries), logs $(( $2 / 1048576 )) MB packed"
    echo "   messages of tar on the node:"; ssh -n "root@$ip" "cat /root/${TAG}_pack.err" | sed 's/^/      /'
    need_kb=$(( ($1 * 16 + $2) / 1024 ))
    free_kb=$(df -k "$TARGET" | awk 'NR==2{print $4}')
    if [ "$free_kb" -lt "$need_kb" ]; then
        echo "   NOT DOWNLOADED: about $(( need_kb / 1048576 )) GB needed, $(( free_kb / 1048576 )) GB free. The archives stay on the node."
        problems="$problems $node:disk"; continue
    fi
    mkdir -p "$TARGET/$node"
    if ! scp -q -o StrictHostKeyChecking=no "root@$ip:/root/${TAG}_$node.tgz" "root@$ip:/root/${TAG}_${node}_logs.tar.xz" "$TARGET/$node/"; then
        echo "   COPY FAILED"; problems="$problems $node:copy"; continue
    fi
    # The copies must be the files of the node, byte for byte.
    local_a=$(shasum -a 256 "$TARGET/$node/${TAG}_$node.tgz" | cut -d' ' -f1)
    local_b=$(shasum -a 256 "$TARGET/$node/${TAG}_${node}_logs.tar.xz" | cut -d' ' -f1)
    if [ "$local_a" != "$3" ] || [ "$local_b" != "$4" ]; then
        echo "   CHECKSUM DIFFERS from the node"; problems="$problems $node:checksum"; continue
    fi
    if ! tar xzf "$TARGET/$node/${TAG}_$node.tgz" -C "$TARGET/$node"; then
        echo "   UNPACKING FAILED"; problems="$problems $node:unpack"; continue
    fi
    unpacked=$(find "$TARGET/$node/files" | wc -l | tr -d ' ')
    echo "   checksums equal; unpacked into $TARGET/$node ($unpacked entries of $5; logs kept packed)"
    [ "$unpacked" -ge "$5" ] || { problems="$problems $node:entries"; continue; }
    echo "$node $ip $3 $4" >> "$TARGET/collected_nodes.txt"
    collected=$((collected + 1))
done < "$IPS_FILE"
echo "Collected $collected of $listed nodes into $TARGET"
if [ "$collected" -ne "$listed" ] || [ -n "$problems" ]; then
    echo "NOT COMPLETE:$problems"
    exit 1
fi
echo "COMPLETE: every node collected, checksums equal, no failed JVM in any jobs.csv."
